source:
source note sys.dataset(fields: [title, subtitle, summary, as_of, metric1_value, metric2_value, pick1_title, pick1_body, pick2_title, pick2_body])

state mode { shape: enum[brief, code, details], initial: .brief }
event code { mode: set(.code) }
event details { mode: set(.details) }
event back { mode: set(.brief) }

copy app { class: vocabulary, en: "Mail · Simulation" }
copy b_code { class: vocabulary, en: "Show code" }
copy b_details { class: vocabulary, en: "Details" }
copy b_back { class: vocabulary, en: "Back" }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: note.as_of)
    }
    when mode == .brief {
      TextTitle(text: note.title, width: .fill)
      TextCaption(text: note.metric1_value, width: .fill)
      TextCaption(text: note.pick2_body, width: .fill)
      Chip(text: copy.b_code, on_tap: code, tone: .primary)
      Chip(text: copy.b_details, on_tap: details)
    }
    when mode == .code {
      TextCaption(text: note.subtitle, width: .fill)
      TextEyebrow(text: note.pick1_title)
      TextTitle(text: note.pick1_body, width: .fill)
      TextCaption(text: note.pick2_title, width: .fill)
      Chip(text: copy.b_back, on_tap: back, tone: .primary)
    }
    when mode == .details {
      TextCaption(text: note.subtitle, width: .fill)
      TextBody(text: note.summary, width: .fill)
      TextCaption(text: note.metric2_value, width: .fill)
      TextCaption(text: note.metric1_value, width: .fill)
      Chip(text: copy.b_back, on_tap: back, tone: .primary)
    }
  }
}
